import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for matrix multiplication with larger tiles and register blocking
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define REG_TILE 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int bx = blockIdx.x, by = blockIdx.y;
    int tx = threadIdx.x, ty = threadIdx.y;

    int row_base = by * TILE_SIZE + ty;
    int col_base = bx * TILE_SIZE + tx;

    float c_reg[REG_TILE][REG_TILE] = {0.0f};

    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Load tiles into shared memory with coalesced access
        for (int i = 0; i < REG_TILE; i++) {
            for (int j = 0; j < REG_TILE; j++) {
                int row = row_base + i * (TILE_SIZE / REG_TILE);
                int col = col_base + j * (TILE_SIZE / REG_TILE);
                int k_idx = t * TILE_SIZE + tx + j * (TILE_SIZE / REG_TILE);

                if (row < N && k_idx < N) {
                    As[ty + i * (TILE_SIZE / REG_TILE)][tx + j * (TILE_SIZE / REG_TILE)] = 
                        A[row * N + k_idx];
                } else {
                    As[ty + i * (TILE_SIZE / REG_TILE)][tx + j * (TILE_SIZE / REG_TILE)] = 0.0f;
                }

                int k_row = t * TILE_SIZE + ty + i * (TILE_SIZE / REG_TILE);
                if (col < N && k_row < N) {
                    Bs[ty + i * (TILE_SIZE / REG_TILE)][tx + j * (TILE_SIZE / REG_TILE)] = 
                        B[k_row * N + col];
                } else {
                    Bs[ty + i * (TILE_SIZE / REG_TILE)][tx + j * (TILE_SIZE / REG_TILE)] = 0.0f;
                }
            }
        }

        __syncthreads();

        // Compute using register blocking
        for (int k = 0; k < TILE_SIZE; k++) {
            for (int i = 0; i < REG_TILE; i++) {
                for (int j = 0; j < REG_TILE; j++) {
                    c_reg[i][j] += As[ty + i * (TILE_SIZE / REG_TILE)][k] * 
                                   Bs[k][tx + j * (TILE_SIZE / REG_TILE)];
                }
            }
        }

        __syncthreads();
    }

    // Write results back to global memory
    for (int i = 0; i < REG_TILE; i++) {
        for (int j = 0; j < REG_TILE; j++) {
            int row = row_base + i * (TILE_SIZE / REG_TILE);
            int col = col_base + j * (TILE_SIZE / REG_TILE);
            if (row < N && col < N) {
                C[row * N + col] = c_reg[i][j];
            }
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    auto N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    dim3 block(TILE_SIZE / REG_TILE, TILE_SIZE / REG_TILE);
    dim3 grid((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);

    matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(), 
        B.data_ptr<float>(), 
        C.data_ptr<float>(), 
        N
    );

    return C;
}
"""

