import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for matrix multiplication with vectorized access and optimizations
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define BLOCK_SIZE 8
#define UNROLL_FACTOR 8

__global__ void matmul_kernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int N) {
    __shared__ float As[TILE_SIZE][TILE_SIZE + 1]; // +1 to avoid bank conflicts
    __shared__ float Bs[TILE_SIZE][TILE_SIZE + 1];

    int bx = blockIdx.x, by = blockIdx.y;
    int tx = threadIdx.x, ty = threadIdx.y;

    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    float c_reg[BLOCK_SIZE][BLOCK_SIZE] = {0.0f};

    // Process tiles
    for (int t = 0; t < N; t += TILE_SIZE) {
        // Load A tile with vectorized access when possible
        #pragma unroll
        for (int i = 0; i < BLOCK_SIZE; i++) {
            #pragma unroll
            for (int j = 0; j < BLOCK_SIZE; j++) {
                int a_row = by * TILE_SIZE + ty * BLOCK_SIZE + i;
                int a_col = t + tx * BLOCK_SIZE + j;
                int b_row = t + ty * BLOCK_SIZE + i;
                int b_col = bx * TILE_SIZE + tx * BLOCK_SIZE + j;

                if (a_row < N && a_col < N) {
                    As[ty * BLOCK_SIZE + i][tx * BLOCK_SIZE + j] = A[a_row * N + a_col];
                } else {
                    As[ty * BLOCK_SIZE + i][tx * BLOCK_SIZE + j] = 0.0f;
                }

                if (b_row < N && b_col < N) {
                    Bs[ty * BLOCK_SIZE + i][tx * BLOCK_SIZE + j] = B[b_row * N + b_col];
                } else {
                    Bs[ty * BLOCK_SIZE + i][tx * BLOCK_SIZE + j] = 0.0f;
                }
            }
        }

        __syncthreads();

        // Compute with unrolled loops
        #pragma unroll UNROLL_FACTOR
        for (int k = 0; k < TILE_SIZE; k++) {
            #pragma unroll
            for (int i = 0; i < BLOCK_SIZE; i++) {
                float a_val = As[ty * BLOCK_SIZE + i][k];
                #pragma unroll
                for (int j = 0; j < BLOCK_SIZE; j++) {
                    c_reg[i][j] += a_val * Bs[k][tx * BLOCK_SIZE + j];
                }
            }
        }

        __syncthreads();
    }

    // Write results back with coalesced access
    #pragma unroll
    for (int i = 0; i < BLOCK_SIZE; i++) {
        #pragma unroll
        for (int j = 0; j < BLOCK_SIZE; j++) {
            int out_row = by * TILE_SIZE + ty * BLOCK_SIZE + i;
            int out_col = bx * TILE_SIZE + tx * BLOCK_SIZE + j;
            if (out_row < N && out_col < N) {
                C[out_row * N + out_col] = c_reg[i][j];
            }
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    auto N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    const int threads_per_block = TILE_SIZE / BLOCK_SIZE;
    dim3 block(threads_per_block, threads_per_block);
    dim3 grid((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);

    matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(), 
        B.data_ptr<float>(), 
        C.data_ptr<float>(), 
        N
    );

    return C;
}
"""

matmul_cpp_source = (
    "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"
)

# Compile the inline CUDA code for matrix multiplication
matmul = load_inline(
    name="matmul",
    cpp_sources=matmul_cpp_source,
    cuda_sources=matmul_source,
    functions=["matmul_cuda"],
    verbose=True,
    extra_cflags=["-O3"],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.matmul = matmul

    def forward(self, A, B):
        return self.matmul.matmul_cuda(A, B)"}

